// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.json;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.junit.jupiter.api.Test;

/**
 * Edge cases for {@code jsonf:jsonKeys}, {@code jsonf:jsonArrayLength}, {@code jsonf:jsonObject},
 * {@code jsonf:jsonArray} and {@code jsonf:jsonSet}.
 */
class JsonKeysLengthObjectArraySetEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String XSD_NS = "http://www.w3.org/2001/XMLSchema#";

	private static Literal json(String s) {
		return VF.createLiteral(s, CoreDatatype.RDF.JSON);
	}

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	private static Literal integer(long v) {
		return VF.createLiteral(BigInteger.valueOf(v));
	}

	private static String typed(String label, String localName) {
		return "{\"@value\":\"" + label + "\",\"@type\":\"" + XSD_NS + localName + "\"}";
	}

	// ------------------------------------------------------------------ jsonKeys / jsonArrayLength

	@Test
	void keysOnArrayAndLengthOnObjectAreErrors() {
		assertThatThrownBy(() -> new JsonKeys().evaluate(VF, json("[1,2]")))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("requires a JSON object");
		assertThatThrownBy(() -> new JsonKeys().evaluate(VF, json("{\"a\":[1]}"), str("$.a")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonKeys().evaluate(VF, json("\"s\"")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonArrayLength().evaluate(VF, json("{\"a\":1}")))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("requires a JSON array");
		assertThatThrownBy(() -> new JsonArrayLength().evaluate(VF, json("[{\"a\":1}]"), str("$[0]")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonArrayLength().evaluate(VF, json("7")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void emptyObjectAndArrayGiveEmptyKeysAndZeroLength() {
		assertThat(new JsonKeys().evaluate(VF, json("{}"))).isEqualTo(json("[]"));
		assertThat(new JsonKeys().evaluate(VF, json("[{}]"), str("$[0]"))).isEqualTo(json("[]"));
		assertThat(new JsonArrayLength().evaluate(VF, json("[]"))).isEqualTo(integer(0));
		assertThat(new JsonArrayLength().evaluate(VF, json("{\"a\":[]}"), str("$.a"))).isEqualTo(integer(0));
		assertThat(new JsonArrayLength().evaluate(VF, json("[[],[1]]"), str("$[1]"))).isEqualTo(integer(1));
		assertThat(((Literal) new JsonArrayLength().evaluate(VF, json("[null,null]"))).getCoreDatatype())
				.isEqualTo(CoreDatatype.XSD.INTEGER);
		assertThat(new JsonArrayLength().evaluate(VF, json("[null,null]"))).isEqualTo(integer(2));
	}

	@Test
	void keysKeepInsertionOrderIncludingUnicodeAndEmptyKeys() {
		Literal document = json("{\"z\":1,\"\":2,\"\u00fc\uD83D\uDE00\":3,\"a\":4,\"with \\\"quote\\\"\":5}");
		assertThat(new JsonKeys().evaluate(VF, document))
				.isEqualTo(json("[\"z\",\"\",\"\u00fc\uD83D\uDE00\",\"a\",\"with \\\"quote\\\"\"]"));
		// the empty key is addressable through the bracket syntax
		assertThat(new JsonValue().evaluate(VF, document, str("$['']"))).isEqualTo(integer(2));
		assertThat(new JsonValue().evaluate(VF, document, str("$['\u00fc\uD83D\uDE00']"))).isEqualTo(integer(3));
	}

	@Test
	void keysAndLengthRequireExactlyOneSelectedNode() {
		Literal document = json("{\"a\":[{\"k\":1},{\"k\":2}],\"o\":{\"x\":{}}}");
		for (String path : List.of("$.a[*]", "$..k", "$.missing", "$.a[5]")) {
			assertThatThrownBy(() -> new JsonKeys().evaluate(VF, document, str(path)))
					.as("jsonKeys %s", path)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new JsonArrayLength().evaluate(VF, document, str(path)))
					.as("jsonArrayLength %s", path)
					.isInstanceOf(ValueExprEvaluationException.class);
		}
		assertThat(new JsonKeys().evaluate(VF, document, str("$.o.*"))).isEqualTo(json("[]"));
		assertThat(new JsonKeys().evaluate(VF, document, str("$.a[-1]"))).isEqualTo(json("[\"k\"]"));
	}

	// ------------------------------------------------------------------ jsonObject / jsonArray

	@Test
	void jsonObjectOddArgumentsAreAnErrorAndZeroArgumentsGiveEmptyContainers() {
		assertThat(new JsonObject().evaluate(VF)).isEqualTo(json("{}"));
		assertThat(new JsonArray().evaluate(VF)).isEqualTo(json("[]"));
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, str("a")))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("even number of arguments");
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, str("a"), integer(1), str("b")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new JsonArray().evaluate(VF, integer(1))).isEqualTo(json("[1]"));
	}

	@Test
	void jsonObjectKeysAreLexicalFormsAndDuplicatesLastWins() {
		// pins current behaviour: a non-string literal key is stringified via its lexical form
		assertThat(new JsonObject().evaluate(VF, integer(1), str("one"))).isEqualTo(json("{\"1\":\"one\"}"));
		assertThat(new JsonObject().evaluate(VF, VF.createLiteral(true), str("t")))
				.isEqualTo(json("{\"true\":\"t\"}"));
		assertThat(new JsonObject().evaluate(VF, VF.createLiteral("k", "en"), str("v")))
				.isEqualTo(json("{\"k\":\"v\"}"));
		// an IRI or blank node key is an error
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, VF.createIRI("urn:k"), str("v")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, VF.createBNode("k"), str("v")))
				.isInstanceOf(ValueExprEvaluationException.class);
		// duplicate keys: last value wins, position of the first occurrence
		assertThat(new JsonObject().evaluate(VF, str("a"), integer(1), str("b"), integer(2), str("a"), integer(3)))
				.isEqualTo(json("{\"a\":3,\"b\":2}"));
		assertThat(new JsonObject().evaluate(VF, str(""), integer(1))).isEqualTo(json("{\"\":1}"));
	}

	@Test
	void jsonObjectAndArrayValueEncodings() {
		// pins current behaviour: an unbound (null) value is an evaluation error, not JSON null
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, str("a"), (Value) null))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonArray().evaluate(VF, integer(1), null))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new JsonObject().evaluate(VF, str("i"), VF.createIRI("urn:x"), str("b"), VF.createBNode("n1")))
				.isEqualTo(json("{\"i\":{\"@id\":\"urn:x\"},\"b\":{\"@id\":\"_:n1\"}}"));
		// rdf:JSON values are embedded structurally, never as strings
		assertThat(new JsonObject().evaluate(VF, str("c"), json("{\"k\":[1,{\"d\":true}]}")))
				.isEqualTo(json("{\"c\":{\"k\":[1,{\"d\":true}]}}"));
		assertThat(new JsonArray().evaluate(VF, json("[1,2]"), json("\"s\""), json("null")))
				.isEqualTo(json("[[1,2],\"s\",null]"));
		// a plain string that happens to look like JSON stays a string
		assertThat(new JsonArray().evaluate(VF, str("[1,2]"))).isEqualTo(json("[\"[1,2]\"]"));
		// a malformed rdf:JSON value is an evaluation error
		assertThatThrownBy(() -> new JsonArray().evaluate(VF, json("{broken")))
				.isInstanceOf(ValueExprEvaluationException.class);
		// a triple term cannot be represented
		assertThatThrownBy(() -> new JsonArray().evaluate(VF,
				VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o"))))
						.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void jsonObjectNumericValueEncodings() {
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("1", XSD.BYTE)).getLabel())
				.isEqualTo("[" + typed("1", "byte") + "]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("01", XSD.INTEGER)).getLabel())
				.isEqualTo("[" + typed("01", "integer") + "]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("+1", XSD.INTEGER)).getLabel())
				.isEqualTo("[" + typed("+1", "integer") + "]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("1", XSD.INTEGER)).getLabel()).isEqualTo("[1]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral(Double.NaN)).getLabel())
				.isEqualTo("[" + typed("NaN", "double") + "]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral(Double.POSITIVE_INFINITY)).getLabel())
				.isEqualTo("[" + typed("INF", "double") + "]");
		// decimals: a fractional canonical form is bare, an integral-looking decimal keeps its type via tagging
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral(new BigDecimal("1.50"))).getLabel())
				.isEqualTo("[1.50]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("1", XSD.DECIMAL)).getLabel())
				.isEqualTo("[" + typed("1", "decimal") + "]");
		// doubles: only an exponent lexical form that matches Double.toString is bare
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("1.0E10", XSD.DOUBLE)).getLabel())
				.isEqualTo("[1.0E10]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral(1.5)).getLabel())
				.isEqualTo("[" + typed("1.5", "double") + "]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral(1.5f)).getLabel())
				.isEqualTo("[" + typed("1.5", "float") + "]");
		// booleans: canonical lexical forms are bare, "1" keeps its type
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("true", XSD.BOOLEAN)).getLabel())
				.isEqualTo("[true]");
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("1", XSD.BOOLEAN)).getLabel())
				.isEqualTo("[" + typed("1", "boolean") + "]");
		// a malformed integer keeps its lexical form and type
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral("abc", XSD.INTEGER)).getLabel())
				.isEqualTo("[" + typed("abc", "integer") + "]");
	}

	@Test
	void everyTermKindRoundTripsThroughJsonArrayAndJsonValue() {
		List<Value> terms = List.of(VF.createIRI("http://example.org/a#frag"), VF.createBNode("node1"), str("plain"),
				str(""), VF.createLiteral("x", "en"), VF.createLiteral("x", "en-GB"),
				VF.createLiteral("x", "ar", Literal.BaseDirection.RTL),
				VF.createLiteral("x", "en", Literal.BaseDirection.LTR),
				VF.createLiteral("2024-02-29", XSD.DATE), integer(42), integer(-1),
				VF.createLiteral(new BigInteger("123456789012345678901234567890")),
				VF.createLiteral(new BigDecimal("2.50")), VF.createLiteral(new BigDecimal("0.0000001")),
				VF.createLiteral("1", XSD.DECIMAL), VF.createLiteral(1.5), VF.createLiteral(1.0E10),
				VF.createLiteral(Double.NaN), VF.createLiteral(Double.NEGATIVE_INFINITY), VF.createLiteral(-0.0),
				VF.createLiteral(1.5f), VF.createLiteral(true), VF.createLiteral("false", XSD.BOOLEAN),
				VF.createLiteral("1", XSD.BOOLEAN), VF.createLiteral("1", XSD.BYTE),
				VF.createLiteral("01", XSD.INTEGER),
				VF.createLiteral("abc", XSD.INTEGER), VF.createLiteral("1e5", XSD.DECIMAL),
				VF.createLiteral("{\"not\":\"json literal\"}"), VF.createLiteral("x", VF.createIRI("urn:custom")),
				VF.createLiteral("\"quoted\" and \\ backslash \n newline"));
		for (Value term : terms) {
			Literal array = new JsonArray().evaluate(VF, term);
			assertThat(new JsonValue().evaluate(VF, array, str("$[0]"))).as(term.toString()).isEqualTo(term);
			assertThat(new JsonValue().evaluate(VF, new JsonObject().evaluate(VF, str("k"), term), str("$.k")))
					.as(term.toString())
					.isEqualTo(term);
		}
		// pins current behaviour: an rdf:JSON object or array element is structural, so jsonValue rejects it and
		// jsonQuery returns it (in canonical form); an rdf:JSON scalar comes back as the plain scalar term
		Literal structured = json("{\"k\":[1, 2]}");
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, new JsonArray().evaluate(VF, structured), str("$[0]")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new JsonQuery().evaluate(VF, new JsonArray().evaluate(VF, structured), str("$[0]")))
				.isEqualTo(json("{\"k\":[1,2]}"));
		assertThat(new JsonValue().evaluate(VF, new JsonArray().evaluate(VF, json("\"abc\"")), str("$[0]")))
				.isEqualTo(str("abc"));
	}

	// ------------------------------------------------------------------ jsonSet

	private static Literal set(String document, String path, Value value) {
		return new JsonSet().evaluate(VF, json(document), str(path), value);
	}

	@Test
	void jsonSetReplacesExistingAndCreatesMissingKeys() {
		assertThat(set("{\"a\":1,\"b\":2}", "$.a", integer(9))).isEqualTo(json("{\"a\":9,\"b\":2}"));
		assertThat(set("{\"a\":1}", "$.b", str("x"))).isEqualTo(json("{\"a\":1,\"b\":\"x\"}"));
		assertThat(set("{\"a\":{\"b\":1}}", "$.a.c", VF.createLiteral(true)))
				.isEqualTo(json("{\"a\":{\"b\":1,\"c\":true}}"));
		assertThat(set("{}", "$['a b']", integer(1))).isEqualTo(json("{\"a b\":1}"));
		// replacing a scalar with a container and a container with a scalar both work
		assertThat(set("{\"a\":1}", "$.a", json("[1]"))).isEqualTo(json("{\"a\":[1]}"));
		assertThat(set("{\"a\":[1]}", "$.a", integer(1))).isEqualTo(json("{\"a\":1}"));
	}

	@Test
	void jsonSetMissingIntermediatesAreAutoCreatedExceptArrayIndices() {
		// pins current behaviour: missing intermediate objects/arrays are created based on the following step
		assertThat(set("{\"a\":1}", "$.x.y", integer(2))).isEqualTo(json("{\"a\":1,\"x\":{\"y\":2}}"));
		assertThat(set("{\"a\":1}", "$.x[0]", integer(2))).isEqualTo(json("{\"a\":1,\"x\":[2]}"));
		assertThat(set("{\"a\":1}", "$.x.y.z", integer(2))).isEqualTo(json("{\"a\":1,\"x\":{\"y\":{\"z\":2}}}"));
		// a scalar in the way of an intermediate key is replaced by the created container
		assertThat(set("{\"a\":1}", "$.a.b", integer(2))).isEqualTo(json("{\"a\":{\"b\":2}}"));
		assertThat(set("[1]", "$[0].k", integer(2))).isEqualTo(json("[{\"k\":2}]"));
		// but an intermediate array index that does not exist is an error rather than being created
		assertThatThrownBy(() -> set("{\"a\":1}", "$.x[0].z", integer(2)))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("index out of range");
		assertThatThrownBy(() -> set("[1]", "$[3].z", integer(2)))
				.isInstanceOf(ValueExprEvaluationException.class);
		// a key step on an array and an index step on an object are errors
		assertThatThrownBy(() -> set("[1]", "$.k", integer(2)))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("non-object");
		assertThatThrownBy(() -> set("{\"a\":1}", "$[0]", integer(2)))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("non-array");
	}

	@Test
	void jsonSetArrayIndexSemantics() {
		assertThat(set("[1,2,3]", "$[1]", integer(9))).isEqualTo(json("[1,9,3]"));
		assertThat(set("[1,2,3]", "$[0]", integer(9))).isEqualTo(json("[9,2,3]"));
		// index == length appends
		assertThat(set("[1,2,3]", "$[3]", integer(9))).isEqualTo(json("[1,2,3,9]"));
		// pins current behaviour: an index beyond the end also appends (no padding, no error)
		assertThat(set("[1,2,3]", "$[10]", integer(9))).isEqualTo(json("[1,2,3,9]"));
		assertThat(set("[]", "$[0]", integer(9))).isEqualTo(json("[9]"));
		// negative indices count from the end; pins current behaviour: too negative prepends
		assertThat(set("[1,2,3]", "$[-1]", integer(9))).isEqualTo(json("[1,2,9]"));
		assertThat(set("[1,2,3]", "$[-3]", integer(9))).isEqualTo(json("[9,2,3]"));
		assertThat(set("[1,2,3]", "$[-10]", integer(9))).isEqualTo(json("[9,1,2,3]"));
		// nested
		assertThat(set("{\"l\":[[1],[2]]}", "$.l[-1][0]", integer(9))).isEqualTo(json("{\"l\":[[1],[9]]}"));
	}

	@Test
	void jsonSetOnRootReplacesTheWholeDocument() {
		assertThat(set("{\"a\":1}", "$", integer(5))).isEqualTo(json("5"));
		assertThat(set("{\"a\":1}", "$", json("{\"n\":[1]}"))).isEqualTo(json("{\"n\":[1]}"));
		assertThat(set("[1,2]", "$", str("x"))).isEqualTo(json("\"x\""));
		assertThat(set("1", "$", VF.createIRI("urn:x"))).isEqualTo(json("{\"@id\":\"urn:x\"}"));
		assertThat(set("1", "", integer(2))).isEqualTo(json("2"));
	}

	@Test
	void jsonSetValueEncodingsAndUnboundValue() {
		assertThat(set("{\"a\":1}", "$.a", json("{\"k\":[1]}"))).isEqualTo(json("{\"a\":{\"k\":[1]}}"));
		assertThat(set("{\"a\":1}", "$.a", json("null"))).isEqualTo(json("{\"a\":null}"));
		assertThat(set("{\"a\":1}", "$.a", VF.createIRI("urn:x"))).isEqualTo(json("{\"a\":{\"@id\":\"urn:x\"}}"));
		assertThat(set("{\"a\":1}", "$.a", VF.createLiteral("x", "en")))
				.isEqualTo(json("{\"a\":{\"@value\":\"x\",\"@language\":\"en\"}}"));
		assertThat(set("{\"a\":1}", "$.a", VF.createLiteral("1", XSD.BYTE)).getLabel())
				.isEqualTo("{\"a\":" + typed("1", "byte") + "}");
		assertThatThrownBy(() -> set("{\"a\":1}", "$.a", null)).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> set("{\"a\":1}", "$.a", json("{bad")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> set("{\"a\":1}", "$.a",
				VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o"))))
						.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void jsonSetIsPureAndLeavesTheSourceUntouched() {
		Literal source = json("{\"a\":{\"b\":[1,2]},\"c\":1}");
		// warm the shared parse cache with the source so a mutation would be observable through later reads
		assertThat(new JsonValue().evaluate(VF, source, str("$.c"))).isEqualTo(integer(1));
		Literal first = new JsonSet().evaluate(VF, source, str("$.a.b[0]"), integer(9));
		Literal second = new JsonSet().evaluate(VF, source, str("$.a.b[0]"), integer(9));
		assertThat(first).isEqualTo(second).isEqualTo(json("{\"a\":{\"b\":[9,2]},\"c\":1}"));
		Literal appended = new JsonSet().evaluate(VF, source, str("$.a.b[5]"), integer(7));
		assertThat(appended).isEqualTo(json("{\"a\":{\"b\":[1,2,7]},\"c\":1}"));
		Literal created = new JsonSet().evaluate(VF, source, str("$.d.e"), integer(7));
		assertThat(created).isEqualTo(json("{\"a\":{\"b\":[1,2]},\"c\":1,\"d\":{\"e\":7}}"));
		// the source document still reads as before, from every function
		assertThat(new JsonQuery().evaluate(VF, source, str("$"))).isEqualTo(source);
		assertThat(new JsonValue().evaluate(VF, source, str("$.a.b[0]"))).isEqualTo(integer(1));
		assertThat(new JsonArrayLength().evaluate(VF, source, str("$.a.b"))).isEqualTo(integer(2));
		assertThat(new JsonKeys().evaluate(VF, source)).isEqualTo(json("[\"a\",\"c\"]"));
		// setting into the result of a set does not affect the intermediate result either
		Literal chained = new JsonSet().evaluate(VF, first, str("$.c"), integer(2));
		assertThat(chained).isEqualTo(json("{\"a\":{\"b\":[9,2]},\"c\":2}"));
		assertThat(new JsonQuery().evaluate(VF, first, str("$"))).isEqualTo(first);
	}
}
